export const DATA_23: ReadingTest[] = [
  { id: "rd-028", num: 28, title: "Đề 028", timeMin: 60, parts: [
    { title: "The Coffee Culture of Vietnam", paragraphs: ["Coffee arrived in Vietnam during the nineteenth century, brought by French colonists who planted the first trees in the country's cooler highland regions. What began as an imported crop, however, eventually grew into something the French themselves would barely recognize, since Vietnamese drinkers adapted both the beans and the brewing method to suit local taste and available ingredients. Today, coffee is woven so tightly into everyday life that many people drink it not simply for the caffeine but as an excuse to sit, talk, and watch the street go by for an hour or more.", "Most Vietnamese coffee is made from robusta beans rather than the milder arabica variety favored in many Western countries, giving the drink a bold intensity in flavor rather than a gentle taste. This intensity is traditionally balanced with sweetened condensed milk, a pairing that dates back to a time when fresh milk was difficult to find and expensive to store. The coffee itself is usually brewed one cup at a time through a small metal filter called a phin, which sits directly on top of the glass and lets hot water slowly drip through the grounds over several minutes.", "Beyond the drink itself, coffee shops occupy a central place in Vietnamese social life. Many cafes furnish their sidewalks with small plastic stools rather than indoor tables, encouraging customers to sit facing the street and watch traffic, vendors, and neighbors pass by. This unhurried, sociable atmosphere is one reason many regulars return to the same shop for years. It has less to do with the coffee's exact flavor than with the ritual of sitting and watching the world go by. A cup can often be bought for a price low enough that students and office workers alike treat a coffee shop as a natural extension of their daily routine, a place to meet friends, finish homework, or simply pause between errands without feeling any pressure to order something more expensive or leave quickly.", "Coffee is not only a cultural habit but also a major economic activity. Vietnam ranks among the largest coffee-exporting countries in the world, and much of that production comes from small farms scattered across the Central Highlands, where the climate and soil suit robusta cultivation particularly well. Hundreds of thousands of farming households depend on coffee for a significant part of their income, which means that swings in the global coffee price can directly affect family budgets far from any city coffee shop.", "In recent years, a younger generation of café owners has begun experimenting with the tradition rather than simply preserving it. Specialty shops now serve pour-over coffee alongside the classic phin, and inventive drinks such as egg coffee, made by whipping egg yolk with sugar into a thick, sweet foam, have attracted attention from visitors and locals alike. Whether these newer styles will eventually replace the older stool-and-sidewalk experience or simply exist beside it remains an open question that each neighborhood seems to be answering slightly differently."], questions: [{ q: "According to the passage, why is Vietnamese coffee traditionally served with sweetened condensed milk?", options: ["Fresh milk used to be hard to find and costly to keep.", "Most Vietnamese coffee is made from robusta beans rather than arabica.", "French colonists specifically requested that milk be added to coffee.", "Condensed milk became popular because fresh milk was cheap and plentiful."], answer: 0 }, { q: "The word \"intensity\" in paragraph 2 is closest in meaning to _______.", options: ["sweetness", "freshness", "boldness", "intent"], answer: 2 }, { q: "Which of the following best expresses the main idea of the passage?", options: ["Coffee is traditionally brewed one cup at a time through a phin.", "Coffee in Vietnam is both a daily social ritual and an important export.", "Coffee in Vietnam matters mainly as an export, not a social habit.", "Every household in Vietnam earns most of its income from coffee farming."], answer: 1 }, { q: "According to the passage, what economic risk does Vietnam's reliance on coffee create for farming households?", options: ["Vietnam ranks among the largest coffee-exporting countries in the world.", "Only farms outside the Central Highlands face this economic risk.", "Rising global coffee prices have permanently harmed farming households' income.", "Falling global coffee prices can hurt farm family incomes directly."], answer: 3 }, { q: "According to the passage, which of the following is NOT mentioned as a feature of Vietnamese coffee shop culture?", options: ["Free wireless internet provided at every single coffee shop.", "Small plastic stools placed facing the busy street.", "Affordable prices that suit students and office workers.", "Egg coffee made from whipped egg yolk and sugar."], answer: 0 }, { q: "The word \"It\" in paragraph 3 refers to _______.", options: ["the same shop itself", "regulars who return yearly", "the relaxed atmosphere", "the coffee's exact flavor"], answer: 2 }, { q: "According to the passage, how did Vietnamese drinkers change the coffee they inherited from French colonists?", options: ["French colonists themselves changed the beans to suit Vietnamese taste.", "They adjusted both the beans and how the coffee was brewed.", "They replaced coffee entirely with a different imported crop.", "They changed only the way coffee is served, not the beans."], answer: 1 }, { q: "The word \"inventive\" in paragraph 5 is closest in meaning to _______.", options: ["extreme", "traditional", "inventoried", "creative"], answer: 3 }, { q: "What can be inferred about the future of Vietnamese coffee shop culture, based on the passage?", options: ["Traditional and newer coffee styles will likely continue existing side by side.", "Specialty pour-over cafes will completely replace the traditional phin within years.", "Fewer tourists visiting Vietnam will cause egg coffee to disappear entirely.", "Vietnam ranks among the largest coffee-exporting countries in the world."], answer: 0 }, { q: "What is the author's overall attitude toward Vietnamese coffee culture?", options: ["Primarily concerned about the financial risks facing coffee-farming households.", "Excited that newer coffee trends will soon dominate the market.", "Appreciative, presenting it as a rich blend of tradition and change.", "Mildly critical of how commercialized Vietnamese coffee shops have become."], answer: 2 }] },
    { title: "The Rise of Rap Culture in Vietnam", paragraphs: ["Rap music entered Vietnam decades after establishing itself in the United States, arriving first through pirated cassette tapes and later through the internet, where a small circle of enthusiasts translated lyrics and imitated flows they barely understood in their original language. For years, mainstream media largely ignored the genre, treating it as a foreign curiosity practiced by a handful of young men in a handful of cities, disconnected from what most Vietnamese listeners considered proper music. That dismissal , however, would not survive the following decade intact.", "It was ultimately television, not the underground scene itself, that dragged Vietnamese rap into the cultural mainstream — and it did so almost by accident. A televised rap competition launched in 2019 exposed a national audience to performers who had spent years honing their craft in near-total obscurity , and the show's unexpected popularity forced radio stations, streaming platforms, and even skeptical parents to reckon with a genre they had previously dismissed. Contestants who had once performed to a few dozen people in small clubs suddenly found their songs streamed millions of times within days of broadcast.", "Adapting rap's rhythmic and lyrical demands to Vietnamese posed challenges that English-language hip-hop never had to solve. Vietnamese is a tonal language, meaning a single syllable can carry several distinct meanings depending on pitch alone, which forces rappers to choose words with unusual care lest a clever rhyme accidentally shift into nonsense or an unintended insult. Some artists have turned this constraint into a stylistic signature, deliberately exploiting near-homophones for wordplay that would be impossible in a non-tonal language, while others draw on regional dialects and slang specific to Hanoi, Ho Chi Minh City, or the central provinces to signal authenticity to a particular local audience.", "Beyond wordplay, a portion of Vietnamese rap has taken on a more pointed social role, addressing generational conflict, economic pressure, and the gap between traditional expectations and the realities young people actually face. Whether this commentary will be permitted to sharpen further remains genuinely uncertain, since content deemed excessively critical or explicit has occasionally drawn official scrutiny, and artists tend to describe navigating this boundary as a matter of ongoing negotiation rather than a fixed set of rules they can simply learn once and follow.", "Commercially, the genre's rise has been difficult to ignore. Streaming platforms now feature dedicated Vietnamese rap playlists that regularly outperform other domestic genres in total plays, and brands eager to reach younger consumers have signed rappers to sponsorship deals that would have been unthinkable a decade earlier. Music festivals built specifically around hip-hop now draw crowds that rival those of longer-established pop concerts, a shift that has persuaded even skeptical concert promoters that the audience for rap is neither small nor temporary.", "Not everyone within the scene welcomes this growth without reservation. Some early adopters argue that mainstream success has diluted the genre's original rawness, pointing to newer artists who prioritize catchy hooks over the lyrical density that once defined the underground scene. Others counter that gatekeeping over what counts as authentic rap has always existed in every country where the genre has spread, and that Vietnamese hip-hop's growing commercial reach does not necessarily mean its artistic ambitions have shrunk to match.", "Whether Vietnamese rap eventually settles into a stable, respected fixture of the country's popular culture, or proves to be a passing commercial wave that fades once novelty wears off, is not a question the current evidence can answer with confidence. What does seem clear is that the genre has already outgrown the dismissive label once applied to it."], questions: [{ q: "According to the passage, what actually caused Vietnamese rap to reach mainstream audiences?", options: ["Rap music entered Vietnam decades after establishing itself in the United States.", "A televised competition show unexpectedly exposed rap to a national audience.", "Underground rap clubs organized national tours that made the genre famous.", "Radio stations independently decided to promote rap before any competition aired."], answer: 1 }, { q: "The word \"obscurity\" in paragraph 2 is closest in meaning to _______.", options: ["fame", "poverty", "obscenity", "anonymity"], answer: 3 }, { q: "Which of the following best expresses the main idea of the passage?", options: ["Vietnamese rap has grown from a dismissed niche into a significant cultural force.", "A televised singing competition in 2019 made several rap contestants famous.", "Vietnamese rap remains a small, dismissed genre ignored by most listeners today.", "Every country's rap scene eventually faces identical authenticity debates and gatekeeping."], answer: 0 }, { q: "According to the passage, which of the following is NOT mentioned as a challenge Vietnamese rappers face?", options: ["Choosing words carefully because Vietnamese is a tonal language.", "Occasional official scrutiny over content considered critical or explicit.", "A complete lack of streaming platforms willing to feature rap.", "Criticism from early fans that mainstream success diluted the genre."], answer: 2 }, { q: "According to the passage, why do some Vietnamese rappers deliberately use near-homophones in their lyrics?", options: ["Vietnamese is tonal, so pitch alone changes a syllable's meaning.", "To create wordplay that only works in a tonal language.", "English-language rappers had reportedly pioneered this specific homophone technique.", "To avoid confusing listeners across different regional Vietnamese dialects."], answer: 1 }, { q: "The phrase \"That dismissal\" in paragraph 1 refers to _______.", options: ["pirated cassette tapes", "a small circle of enthusiasts", "the following decade itself", "rap's dismissal as foreign"], answer: 3 }, { q: "The word \"diluted\" in paragraph 6 is closest in meaning to _______.", options: ["weakened", "destroyed", "commercialized", "deluded"], answer: 0 }, { q: "According to the passage, what has persuaded skeptical concert promoters that rap's audience is significant?", options: ["Streaming platforms now feature dedicated Vietnamese rap playlists.", "Only a handful of fans attend Vietnamese hip-hop festivals currently.", "Hip-hop festivals now draw crowds rivaling established pop concerts.", "Brands have stopped sponsoring rappers due to weak festival turnout."], answer: 2 }, { q: "What can be inferred about the long-term future of Vietnamese rap, based on the passage?", options: ["Vietnamese rap will certainly become a permanently dominant genre nationwide.", "Its future direction is genuinely unsettled and not yet predictable.", "Reduced festival attendance will eventually force rappers back underground entirely.", "Vietnamese is a tonal language, which affects how rap lyrics are written."], answer: 1 }, { q: "What is the author's overall attitude toward the rise of Vietnamese rap?", options: ["Primarily worried that censorship will soon silence Vietnamese rap entirely.", "Enthusiastically certain that rap's commercial success will only keep growing.", "Mildly dismissive of concerns that mainstream success has hurt the genre.", "Balanced curiosity, acknowledging real growth alongside genuine unresolved tensions."], answer: 3 }] },
    { title: "The Science of Circadian Rhythms and Health", paragraphs: ["Nearly every cell in the human body appears to keep track of time independently, yet this distributed timekeeping is coordinated overall by a small cluster of neurons in the brain known as the suprachiasmatic nucleus, which functions as a kind of master clock synchronized primarily by exposure to light. That a structure smaller than a grain of rice could exert such wide-reaching influence over sleep, hormone release, body temperature, and even digestion was not fully appreciated until relatively recent decades of research, when the field of chronobiology began systematically mapping how disrupting this internal schedule produces consequences extending well beyond simple tiredness.", "Beyond the master clock, researchers have identified so-called peripheral clocks operating within the liver, heart, and other organs, each running on a roughly similar rhythm but capable, evidence increasingly suggests, of drifting out of alignment with the central clock under certain conditions. Feeding time, rather than light alone, appears to be a particularly influential cue for these peripheral systems, which may help explain why eating at unconventional hours can produce metabolic effects distinct from, and in some respects independent of, whatever disruption occurs from irregular light exposure or sleep timing.", "Shift workers and long-haul travelers offer some of the clearest evidence of what happens when this coordinated system falls out of sync. Studies tracking night-shift employees over extended periods report elevated rates of metabolic and cardiovascular conditions relative to daytime workers, though researchers are careful to note that shift work correlates with numerous other lifestyle factors, from sleep debt to irregular meal timing, that could plausibly account for some portion of the observed association independent of circadian disruption itself.", "It is specifically the blue-wavelength component of artificial lighting, more than illumination in general, that appears responsible for much of modern life's disruptive effect on the circadian system — a conclusion researchers reached only after ruling out overall brightness as the primary variable. Screens, LED lighting, and other blue-rich sources suppress the release of melatonin, the hormone most directly associated with signaling nighttime to the rest of the body, and they do so far more effectively than the warmer, longer-wavelength light produced by traditional incandescent bulbs or candlelight.", "Individual variation complicates any uniform prescription for managing circadian health. So-called chronotype — the tendency to naturally function as an early riser or a late-night person — appears to have a substantial genetic component, and twin studies estimate that a considerable share of this variation, though by no means all of it, can be attributed to heredity rather than habit or environment. This genetic dimension means that identical light and sleep schedules can produce meaningfully different physiological experiences for two people with different underlying chronotypes.", "Interventions aimed at realigning disrupted rhythms range from carefully timed bright-light exposure to medications administered according to the body's own schedule rather than a fixed clock time, an emerging approach sometimes called chronotherapy. Early results in areas such as cancer treatment suggest that dosing certain drugs at specific times of day can improve effectiveness while reducing side effects, though the field remains young enough that specialists disagree over how broadly these findings will eventually generalize across different drug classes and patient populations.", "Whether workplaces, schools, and hospitals will meaningfully restructure their schedules around this growing body of evidence, rather than treating circadian science as a matter of individual responsibility alone, remains an open institutional question rather than a scientific one. What seems increasingly difficult to dispute is that the body's internal clock is not a minor biological curiosity but a system whose disruption carries consequences serious enough to merit far more deliberate accommodation than it currently receives."], questions: [{ q: "According to the passage, what cue appears particularly influential for peripheral clocks, as distinct from the master clock?", options: ["Light exposure serves as the primary cue for the brain's master clock.", "Feeding time appears especially influential for the body's peripheral clocks.", "Body temperature functions as the main cue driving peripheral organ clocks.", "Peripheral clocks depend entirely on light exposure just like the master clock."], answer: 1 }, { q: "The word \"prescription\" in paragraph 5 is closest in meaning to _______.", options: ["medical order", "genetic component", "description", "recommended approach"], answer: 3 }, { q: "Which of the following best expresses the main idea of the passage?", options: ["The body's internal clock powerfully shapes health, though its disruption and management are complex.", "Blue light from screens suppresses melatonin more than warm light does.", "Circadian disruption is a minor concern compared to genetics in determining health.", "Every person's circadian rhythm responds identically to the same light exposure."], answer: 0 }, { q: "According to the passage, which of the following is NOT mentioned as contributing to health effects associated with shift work?", options: ["Irregular meal timing as a possible confounding factor among shift workers.", "Suppression of melatonin release by blue-wavelength artificial lighting.", "A documented increase in workplace accidents during night shifts.", "Elevated rates of metabolic and cardiovascular conditions among night-shift employees."], answer: 2 }, { q: "According to the passage, why do researchers specifically implicate blue-wavelength light rather than overall brightness?", options: ["Melatonin is the hormone most directly linked to signaling nighttime.", "Traditional incandescent bulbs were found to suppress melatonin most strongly.", "Screens were the very first artificial light source ever studied.", "They ruled out general brightness as the main variable responsible."], answer: 3 }, { q: "The phrase \"these findings\" in paragraph 6 refers to _______.", options: ["cancer treatment itself", "the early research results", "specific times of day", "reduced side effects"], answer: 1 }, { q: "The word \"generalize\" in paragraph 6 is closest in meaning to _______.", options: ["apply broadly", "become popular", "specialize narrowly", "generate"], answer: 0 }, { q: "According to the passage, what do twin studies suggest about chronotype?", options: ["Chronotype refers to a person's natural tendency toward morning or night activity.", "Twin studies found chronotype is determined entirely by genetics alone.", "A considerable, though not complete, share of chronotype is heritable.", "Twin studies found chronotype has no genetic basis whatsoever."], answer: 2 }, { q: "What can be inferred about the future of circadian-based medicine, based on the passage?", options: ["Its wider medical adoption likely depends on further research across drug types and patients.", "Chronotherapy will soon replace conventional drug dosing schedules entirely.", "Reduced side effects from any drug will cause doctors to adopt strict dosing schedules.", "Shift workers show elevated rates of metabolic and cardiovascular conditions."], answer: 0 }, { q: "What is the author's overall attitude toward circadian rhythm science?", options: ["Focused narrowly on urging cancer patients to try chronotherapy immediately.", "Measured and informative, presenting circadian science as significant yet still evolving.", "Alarmed that shift work is silently destroying workers' long-term health.", "Mildly skeptical that circadian rhythms have any real effect on health."], answer: 1 }] },
    { title: "Tipping Points: The Irreversible Risks of Climate Change", paragraphs: ["Climate scientists increasingly distinguish between two categories of environmental change: the gradual, broadly linear warming that dominates most public discussion, and a smaller set of systems that, once pushed past a critical threshold, may shift abruptly into a qualitatively different and largely irreversible state on any timescale relevant to human civilization. Precisely where these thresholds lie remains one of the more contested questions in climate science, not because the underlying phenomenon is doubted, but because the relevant systems are complex enough that pinpointing an exact temperature or carbon-concentration trigger with confidence has proven persistently difficult.", "Among the systems most frequently cited, the West Antarctic Ice Sheet, Arctic permafrost, the Atlantic Meridional Overturning Circulation, and tropical coral reef ecosystems each show some evidence of tipping-point dynamics, though the strength of that evidence, and the confidence with which scientists assign a specific threshold, varies considerably from one system to another. Coral reef die-off, for instance, is documented with comparatively high confidence at specific temperature thresholds already being approached, whereas the exact point at which the West Antarctic Ice Sheet's retreat becomes fully self-sustaining and irreversible remains actively debated, with published estimates spanning a range wide enough that policy built around any single figure would arguably rest on shakier ground than the underlying science actually supports.", "It is the presence of self-reinforcing feedback loops, more than the initial warming trigger itself, that transforms an ordinary gradual change into something qualifying as a genuine tipping point — a distinction that matters because feedback-driven systems can, once initiated, continue shifting even if the original cause is later reversed. Melting Arctic ice, for example, exposes darker ocean water that absorbs more solar radiation than reflective ice did, accelerating further melting in a loop that would keep operating even under a hypothetical scenario of stabilized or slightly declining global emissions.", "This mechanistic understanding does not, however, translate cleanly into the precise early-warning thresholds that policymakers would ideally want. [1] Some researchers have proposed statistical indicators, such as increasing variance or slowing recovery time after minor disturbances, that might signal a system's approach toward a critical threshold before the threshold is actually crossed. [2] These indicators have shown some promise in controlled laboratory and paleoclimate contexts, where the relevant history is comparatively well documented and system boundaries are relatively clean. [3] Applying the same statistical logic to sprawling, poorly bounded real-world systems such as an entire ice sheet or ocean current introduces substantially more noise, meaning any early-warning signal detected in practice would likely arrive with a confidence interval too wide for policymakers to act upon decisively. [4] Consequently, most researchers now frame these indicators as a valuable research direction rather than an operational alarm system ready for immediate deployment.", "A further complication, still more provisional than the threshold estimates discussed above, concerns the possibility that crossing one tipping point could measurably increase the likelihood of triggering others, a phenomenon sometimes described as cascading tipping points. Some modeling studies suggest that Amazon rainforest dieback, for instance, could alter regional precipitation patterns in ways that place additional stress on nearby ice or ocean systems, though the magnitude of this cross-system influence remains far more speculative than the individual tipping points considered in isolation, and several independent research groups have arrived at meaningfully different estimates of how strong this cascading effect might actually be.", "Whether current international emissions pledges, even if fully implemented, would keep global warming safely below the range in which multiple tipping points become likely is a question current models cannot answer with the confidence policymakers might prefer. Some assessments suggest current trajectories carry a non-trivial probability of crossing at least one major threshold before the century's end, while others argue that genuine uncertainty in both the thresholds themselves and the pace of future emissions makes any single probability figure more precise-sounding than the underlying science actually justifies.", "What can be said with somewhat greater confidence is that the irreversibility distinguishing a tipping point from ordinary gradual change removes a form of flexibility that has, until now, been implicitly assumed in most climate policy planning: the option of correcting course later if early action proves insufficient. Whether this narrower margin for error will meaningfully alter the pace of near-term policy decisions, or will instead remain an underappreciated technical footnote to a debate still conducted largely in terms of gradual, reversible change, is not a question the physical science alone can settle."], questions: [{ q: "According to the passage, why is the tipping threshold for coral reef die-off considered more certain than that of the West Antarctic Ice Sheet?", options: ["Coral die-off thresholds are documented with comparatively high confidence already.", "The exact point of irreversible ice sheet retreat remains actively debated.", "Scientists have precisely calculated the exact date coral reefs will disappear.", "Coral reefs are simply less affected by rising ocean temperatures overall."], answer: 0 }, { q: "The word \"provisional\" in paragraph 5 is closest in meaning to _______.", options: ["permanent", "regional", "tentative", "provincial"], answer: 2 }, { q: "Which of the following best expresses the main idea of the passage?", options: ["Melting Arctic ice creates a feedback loop that accelerates further melting.", "Certain climate systems risk crossing irreversible thresholds, though exactly where and how remains genuinely uncertain.", "Scientists now know precisely when each major tipping point will be crossed.", "All climate systems everywhere behave according to identical tipping-point dynamics."], answer: 1 }, { q: "According to the passage, which of the following is NOT mentioned as a documented or proposed climate tipping point?", options: ["The West Antarctic Ice Sheet's accelerating retreat.", "The Atlantic Meridional Overturning Circulation's potential slowdown.", "Coral reef ecosystem die-off at rising ocean temperatures.", "The complete collapse of global ocean fisheries."], answer: 3 }, { q: "Which of the following square brackets [1] , [2] , [3] , or [4] best indicates where the following sentence could be added? 'Yet translating a laboratory-validated concept into a reliable, real-world warning system has proven far harder than the initial statistical logic might suggest.'", options: ["[1]", "[2]", "[3]", "[4]"], answer: 2 }, { q: "The phrase \"this narrower margin for error\" in paragraph 7 refers to _______.", options: ["reduced room to adjust later", "gradual climate policy planning", "the physical science itself", "near-term policy decisions"], answer: 0 }, { q: "The word \"speculative\" in paragraph 5 is closest in meaning to _______.", options: ["impossible", "regional", "spectacular", "unproven"], answer: 3 }, { q: "According to the passage, why do some researchers hesitate to give a single probability figure for crossing a major tipping point this century?", options: ["Some assessments suggest a non-trivial probability of crossing a threshold.", "Uncertainty in both thresholds and future emissions undermines any precise figure.", "Scientists have proven current emissions pledges will definitely avoid all tipping points.", "International pledges have already been fully implemented by every nation."], answer: 1 }, { q: "What can be inferred about the overall confidence level of climate tipping-point science, based on the passage as a whole?", options: ["Confidence is real but varies significantly across different systems and questions.", "Scientists are now fully confident about every tipping point threshold discussed.", "Because thresholds are uncertain, no climate system is actually at meaningful risk.", "Coral reef die-off is documented with comparatively high confidence already."], answer: 0 }, { q: "What is the author's overall attitude toward climate tipping-point science, as conveyed in the passage?", options: ["Entirely certain that every discussed tipping point will be crossed this century.", "Dismissive of early-warning indicators as scientifically worthless in every context.", "Carefully measured, conveying real risk without overstating scientific certainty.", "Mildly reassured that current climate models fully resolve these uncertainties."], answer: 2 }] },
  ] },
  { id: "rd-183", num: 183, title: "Đề 183", timeMin: 60, parts: [
    { title: "Working From Home: The Rise of Remote Work", paragraphs: ["Remote work means doing a job from home, a co-working space, or anywhere other than a traditional office, using the internet and various software tools to stay connected with colleagues. Job titles that once required a physical presence — customer service, software development, marketing — proved, in many cases, adaptable to a remote format once the right tools were in place. Although some people worked remotely before, the practice became far more common after 2020, when many companies were forced to send employees home for health reasons. Once workers and managers discovered that many tasks could be completed just as well outside the office, some companies decided to keep the arrangement permanently rather than return fully to their previous routines.", "Supporters of remote work point to several clear benefits for employees. Workers save time and money by skipping the daily commute, and they often report feeling less stressed without the noise and interruptions of a busy office. A number of surveys report that most employees who have tried remote work would prefer never to return to a full-time office schedule. Parents in particular value the flexibility to arrange their work schedule around school pickups or other family responsibilities. Some studies even suggest that remote workers complete tasks faster, since they face fewer unplanned interruptions from colleagues walking past their desk.", "However, working from home also creates real challenges. Many employees say they feel isolated without daily face-to-face contact with coworkers, and small misunderstandings can grow larger when communication happens only through text messages or video calls. Video calls, while useful, cannot fully replace the small, informal conversations that once happened naturally in hallways or break rooms. It can also be difficult to separate work time from personal time when the same room serves as both an office and a living space. New employees, in particular, often struggle to learn company culture and unwritten workplace rules without watching how experienced colleagues behave in person.", "Because of these mixed effects, many companies have chosen a middle path called hybrid work, where employees come to the office on certain days and work from home on others. Other companies, especially large technology firms, have announced stricter rules requiring staff to return to the office most of the week, arguing that in-person collaboration produces better creative results. Employees who live far from the office often feel these return-to-office rules most strongly, since the change adds hours of commuting back into their week. These differing policies have sometimes caused tension between managers, who often prefer employees nearby, and workers, who have grown used to the flexibility remote work provided.", "Whatever policy a company eventually settles on, few experts expect remote work to disappear completely. Even companies that have called employees back to the office usually allow some remote days, suggesting that a fully rigid , five-day office schedule may belong mostly to the past. Surveys conducted among both managers and employees suggest that most now expect some form of remote or hybrid arrangement to remain standard practice indefinitely. The exact balance between office and home work will likely keep changing for years to come, as companies continue testing what actually works best for their teams."], questions: [{ q: "What is the main idea of the passage?", options: ["Remote work brings both benefits and challenges, and hybrid models will likely continue.", "Hybrid work policies caused all remote work benefits to disappear.", "Only large technology companies benefit from remote work arrangements.", "Remote work will completely disappear once offices fully reopen."], answer: 0 }, { q: "According to the passage, why did remote work become far more common after 2020?", options: ["Because employees demanded better salaries starting in 2020.", "Because many companies sent employees home for health reasons in 2020.", "Because offices became too expensive for companies to maintain.", "Because internet speeds finally became fast enough worldwide in 2020."], answer: 1 }, { q: "According to the passage, what is one benefit remote work offers employees?", options: ["Workers save time and feel less stressed without office noise.", "Workers receive extra vacation days for working remotely.", "Workers spend more time commuting when working from home.", "Workers earn higher salaries when working from home permanently."], answer: 0 }, { q: "According to the passage, what challenge do new employees often face with remote work?", options: ["New employees struggle to learn workplace culture without in-person contact.", "New employees always quit within their first year of remote work.", "New employees earn less money than experienced remote workers.", "New employees prefer remote work more than experienced staff do."], answer: 0 }, { q: "According to the passage, which of the following is NOT mentioned as a challenge of remote work?", options: ["Tension between managers and workers over office policies.", "Feeling isolated without daily face-to-face contact with coworkers.", "Remote employees earn significantly lower salaries than office workers.", "Difficulty separating work time from personal time at home."], answer: 2 }, { q: "The word \"isolated\" in paragraph 3 is closest in meaning to _______.", options: ["unemployed", "insulated", "excited", "alone"], answer: 3 }, { q: "The word \"rigid\" in paragraph 5 is closest in meaning to _______.", options: ["fixed", "expensive", "flexible", "rigged"], answer: 0 }, { q: "The word \"These\" in paragraph 4 refers to _______.", options: ["in-person collaboration", "differing work policies", "large technology firms", "creative results"], answer: 1 }, { q: "What can be inferred from the passage about the future of remote work?", options: ["Some large technology firms have required stricter office attendance.", "Remote work will certainly end completely within the next year.", "Companies deciding hybrid caused remote work to end entirely.", "Most companies will likely keep some remote or hybrid arrangement."], answer: 3 }, { q: "What is the author's overall attitude toward remote work?", options: ["Strongly against companies allowing any remote work at all.", "Focused only on criticizing large technology companies' policies.", "Certain that hybrid work is the only correct policy.", "Balanced, presenting both benefits and challenges of remote work fairly."], answer: 3 }] },
    { title: "TikTok's Numbers: Growth, Revenue, and the Risk of Misreading Statistics", paragraphs: ["TikTok's predecessor, a Shanghai-based app called Douyin, launched domestically in China in September 2016, while the international version debuted the following year and merged in 2018 with Musical.ly, a lip-syncing app already popular among younger users in the United States and Europe. That merger , rather than TikTok's original 2016 launch, is what most analysts credit with triggering the platform's rapid global expansion, since it inherited Musical.ly's existing user base rather than building an international audience from nothing. By 2021, the platform had surpassed one billion monthly active users worldwide, a milestone it reportedly reached faster than any social media platform before it.", "Average daily usage figures vary considerably depending on which market and which year's data is cited, a distinction that matters more than casual comparisons often suggest. Global surveys conducted in 2022 placed average daily use at approximately 95 minutes per user, notably higher than the roughly 50 minutes reported for a leading rival short-video feature launched by a competing platform that same year. Usage in certain Southeast Asian markets, however, has been reported at closer to 125 minutes daily, a figure sometimes mistakenly cited as the platform's global average rather than as a regional outlier .", "Advertising revenue grew from an estimated 4 billion US dollars in 2020 to roughly 18 billion US dollars by 2022, a near fourfold increase within just two years, before growth moderated somewhat as the advertising market matured and competition for the same advertising budgets intensified. Some industry estimates for 2023 place revenue closer to 20 billion US dollars, a figure that represents continued growth but at a considerably slower rate than the near fourfold jump recorded between 2020 and 2022.", "The platform's age demographics have shifted noticeably since its early years. In 2019, users under 18 were estimated to make up roughly 40 percent of the platform's user base in several Western markets, a proportion that had declined to closer to 25 percent by 2023 as older age groups joined in increasing numbers. This shift complicates any claim that TikTok remains primarily a platform for teenagers, even though that early reputation, formed during the 2019 period, continues to shape public perception well after the underlying demographic reality changed.", "The recommendation algorithm's ability to infer user preferences from viewing behavior alone, without requiring users to follow accounts or specify interests explicitly, is frequently cited as central to the platform's engagement levels. Internal research reportedly shared with regulators suggested the algorithm could produce a reasonably tailored recommendation feed after as few as eight to ten videos watched, a claim that, if accurate, would represent a substantially faster personalization process than the hundreds of interactions typically required by earlier recommendation systems built around follower networks and explicit likes.", "Regulatory scrutiny intensified from 2020 onward, beginning with a since-reversed ban attempt in India in mid-2020 and followed by security reviews in several Western countries concerned about data access by a foreign-owned company. A more sustained ban targeting government devices specifically, rather than the general public, took effect in several countries beginning in early 2023, a more limited measure than the outright national bans some commentators mistakenly assumed had already been implemented nationwide by that point.", "Given how rapidly both the platform's user numbers and its regulatory environment have shifted within a single decade, projections about where TikTok's global reach or revenue will stand even five years from now remain, industry analysts generally concede, considerably less reliable than the platform's already-documented growth over its first several years might suggest."], questions: [{ q: "What is the main idea of the passage?", options: ["TikTok's rapid growth involves figures often misread outside their specific context.", "TikTok remains, according to the passage, primarily used by teenagers today.", "TikTok's revenue has grown at the exact same rate every year.", "TikTok's daily usage figures are identical across every global market."], answer: 0 }, { q: "According to the passage, when did TikTok surpass one billion monthly active users worldwide?", options: ["By 2022, alongside its 18 billion dollar revenue milestone.", "By 2023, when its teen user share fell to 25 percent.", "By 2021, faster than any social platform before it.", "By 2018, immediately after merging with Musical.ly."], answer: 2 }, { q: "According to the passage, what does the 125-minutes-per-day figure specifically represent?", options: ["The global average daily usage figure reported in 2022.", "The projected global average usage figure for the year 2023.", "The average usage time for a competing platform's short-video feature.", "A regional figure from certain Southeast Asian markets, not the global average."], answer: 3 }, { q: "According to the passage, how does 2023's estimated revenue growth compare to the growth recorded between 2020 and 2022?", options: ["It represents a complete decline in advertising revenue for TikTok.", "It represents an even faster nearly fourfold increase than before.", "It represents growth at a considerably slower rate than the 2020–2022 jump.", "It represents growth identical in rate to the 2020–2022 period."], answer: 2 }, { q: "According to the passage, which of the following is NOT presented as a factor in regulatory scrutiny of TikTok?", options: ["Security reviews concerned about data access by a foreign-owned company.", "Bans targeting government devices specifically in several countries.", "A since-reversed ban attempt in India in mid-2020.", "A complete worldwide ban on public use enacted in every country by 2023."], answer: 3 }, { q: "The word \"moderated\" in paragraph 3 is closest in meaning to _______.", options: ["advertised", "mediated", "increased sharply", "slowed down"], answer: 3 }, { q: "The word \"outlier\" in paragraph 2 is closest in meaning to _______.", options: ["a competing platform", "an outline", "the typical average", "an unusual exception"], answer: 3 }, { q: "The phrase \"That merger\" in paragraph 1 refers to _______.", options: ["TikTok's original domestic launch", "surpassing one billion users", "the 2018 merger", "the international version's debut"], answer: 2 }, { q: "What can be inferred from the passage about interpreting statistics cited about TikTok?", options: ["Every statistic about TikTok applies equally to all countries and years.", "Regional usage figures are always higher than global figures for every platform.", "Figures like usage minutes or demographics can mislead without their specific context.", "TikTok's revenue figures are the only statistics ever miscited by commentators."], answer: 2 }, { q: "What is the author's overall purpose in this passage?", options: ["To caution readers that TikTok statistics are often cited without needed context.", "To prove that TikTok's regulatory challenges have completely ended.", "To promote TikTok as the fastest-growing platform in history uncritically.", "To argue that TikTok should be banned in every country immediately."], answer: 0 }] },
    { title: "Exercise Before Sleep: Reassessing an Old Warning", paragraphs: ["For decades, sleep hygiene guidelines have cautioned against exercising within several hours of bedtime, a recommendation so consistently repeated across public health materials that few people questioned whether the underlying evidence justified quite so blanket a warning. Only once researchers began systematically comparing exercise timing against objectively measured sleep outcomes, rather than relying on general assumptions about arousal and rest, did the picture begin to look considerably more complicated than the original advice suggested.", "The physiological reasoning behind the traditional caution is not unfounded : vigorous exercise raises core body temperature, and because falling body temperature is one of the physiological signals the brain uses to initiate sleep, exercising too close to bedtime could plausibly delay the temperature drop needed for sleep onset. Exercise also triggers a temporary surge in adrenaline and, to a lesser extent, cortisol, both of which promote alertness rather than the physiological winding-down that precedes sleep, which is precisely the combination of effects the original guidelines were designed to avoid.", "Systematic reviews published over the past decade, however, have found the actual effect on sleep to be considerably smaller and less consistent than the traditional warning implied. Several meta-analyses report that evening exercise, on average, produces no significant delay in sleep onset and may even modestly improve total sleep time, a finding that directly contradicts the blanket caution still printed in many public health brochures. Whether this discrepancy reflects genuine physiological reality or simply methodological differences between older observational studies and newer controlled trials remains a point some sleep researchers continue to debate.", "Much of the apparent contradiction dissolves once timing and intensity are considered separately rather than treated as a single undifferentiated variable. Exercise completed within roughly one hour of bedtime, particularly at high intensity, does appear to delay sleep onset modestly in a meaningful share of study participants, whereas moderate-intensity exercise completed two or more hours before bedtime shows little consistent disruption and, in several studies, correlates with improved sleep quality rather than impaired sleep. This distinction, largely absent from older public health guidance, may explain why so many people report personal experiences that contradict the traditional advice without those experiences necessarily disproving the underlying physiological mechanism.", "Individual variation complicates the picture further, since habitual exercisers appear to tolerate evening workouts with considerably less sleep disruption than occasional exercisers attempting a similarly vigorous session, a difference some researchers attribute to physiological adaptation built up through regular training rather than any difference in the exercise itself. Chronotype — whether a person's natural tendency runs toward earlier or later sleep and wake times — also appears to modulate how strongly evening exercise affects sleep onset, though the mechanism connecting chronotype to this sensitivity remains only partially understood.", "Sleep specialists have responded to this accumulating evidence by shifting away from the blanket avoidance once universally recommended, instead offering more individualized guidance that accounts for exercise intensity, proximity to bedtime, and a person's own exercise habits and observed sleep response. Some clinicians now recommend that patients experiment cautiously with evening exercise timing rather than assuming, on the basis of decades-old general advice, that any evening exertion will necessarily undermine that night's sleep.", "None of this evidence suggests the original caution was entirely mistaken so much as insufficiently specific, since a genuine effect on sleep onset does appear to exist for high-intensity exercise performed very close to bedtime, even as the broader prohibition against any evening exercise whatsoever now looks considerably less justified than it once did. Precisely where the practical threshold lies — how close to bedtime, at what intensity, for which individuals — remains a question researchers are still working to answer with the specificity that clinical guidance ultimately requires."], questions: [{ q: "What is the main idea of the passage?", options: ["Evening exercise has now been proven completely safe for everyone.", "Newer research shows evening exercise's sleep effects depend on several nuanced factors.", "Only chronotype determines whether evening exercise disrupts a person's sleep.", "Traditional sleep guidelines were entirely correct and remain unchanged today."], answer: 1 }, { q: "According to the passage, why might exercising close to bedtime delay sleep onset, according to traditional physiological reasoning?", options: ["Because it improves total sleep time according to newer research.", "Because it raises body temperature and triggers adrenaline and cortisol.", "Because it lowers core body temperature too rapidly before sleep.", "Because it strengthens chronotype's natural tendency toward later sleep."], answer: 1 }, { q: "According to the passage, what pattern do studies show regarding exercise timing and intensity?", options: ["All exercise regardless of timing improves total sleep time equally.", "High-intensity exercise two hours before bedtime consistently disrupts sleep.", "High-intensity exercise within an hour of bedtime may modestly delay sleep onset.", "Moderate exercise close to bedtime always improves sleep quality substantially."], answer: 2 }, { q: "According to the passage, why do habitual exercisers reportedly tolerate evening workouts with less sleep disruption than occasional exercisers?", options: ["Because of physiological adaptation built up through regular training.", "Because habitual exercisers exercise at lower intensity than occasional exercisers.", "Because sleep specialists specifically recommend habitual exercisers avoid evenings.", "Because habitual exercisers have a naturally later chronotype than others."], answer: 0 }, { q: "According to the passage, which of the following is NOT presented as a factor influencing how evening exercise affects sleep?", options: ["The intensity of the exercise performed.", "How close to bedtime the exercise occurs.", "A person's chronotype and habitual exercise patterns.", "The specific type of mattress a person sleeps on."], answer: 3 }, { q: "The word \"unfounded\" in paragraph 2 is closest in meaning to _______.", options: ["without basis", "medically dangerous", "unfamiliar", "well documented"], answer: 0 }, { q: "The word \"modulate\" in paragraph 5 is closest in meaning to _______.", options: ["measure precisely", "modernize", "influence the degree of", "completely eliminate"], answer: 2 }, { q: "The phrase \"this discrepancy\" in paragraph 3 refers to _______.", options: ["the gap between traditional warnings and findings of no sleep delay", "the temperature drop needed for sleep onset", "differences between older and newer study designs", "the surge in adrenaline and cortisol after exercise"], answer: 0 }, { q: "What can be inferred from the passage about the traditional advice against evening exercise?", options: ["The advice was imprecise rather than entirely wrong, given current evidence.", "The traditional advice was entirely wrong and should be completely disregarded.", "The traditional advice was invented specifically to sell sleep aid products.", "Meta-analyses found evening exercise may modestly improve total sleep time."], answer: 0 }, { q: "What is the author's overall purpose in this passage?", options: ["To show how newer evidence refines a once-blanket sleep warning.", "To prove sleep specialists have always been correct about exercise.", "To criticize meta-analyses for contradicting traditional sleep guidelines.", "To argue evening exercise should be mandatory for better sleep."], answer: 0 }] },
    { title: "Homeschooling: Motivations, Evidence, and Regulatory Variation", paragraphs: ["Homeschooling — the practice of educating children primarily at home rather than enrolling them in a public or private school — occupies a peculiar legal position across jurisdictions, tolerated with minimal oversight in some regions while subject to standardized testing requirements, curriculum approval, or periodic assessment in others, a regulatory patchwork that itself complicates any attempt to generalize about homeschooling's effects across the population as a whole.", "Parental motivations for choosing homeschooling have diversified considerably since the practice's modern resurgence in the 1970s and 1980s, when religious conviction and dissatisfaction with secular curricula dominated survey responses; more recent motivations increasingly cite dissatisfaction with school safety, a desire to accommodate a child's particular learning needs, or simply a preference for greater flexibility in scheduling and curriculum pacing, though disentangling which motivation predominates in any given period remains complicated by how survey questions themselves have changed over the decades.", "Claims that homeschooled children achieve academic outcomes superior to their conventionally schooled peers rest, almost entirely, on studies whose samples are not randomly drawn but instead consist of families who volunteered to participate, a self-selection problem that likely inflates apparent achievement gaps, since families willing to complete standardized assessments and share results with researchers are plausibly more academically engaged, on average, than homeschooling families who decline to participate. Whether homeschooled children genuinely outperform their peers once this selection bias is adequately accounted for remains, several methodologists have noted, a question the existing research base is simply not designed to answer with confidence.", "A comparable methodological problem complicates the long-running debate over socialization, in which critics have argued that homeschooled children lack sufficient peer interaction while advocates counter that co-ops, sports leagues, and community activities provide socialization opportunities at least comparable to those a conventional school offers. Existing studies measuring homeschooled children's social skills and emotional adjustment report results that vary considerably depending on which measure of socialization researchers select, which population of homeschoolers they sample, and which comparison group of conventionally schooled peers is used, a degree of methodological inconsistency that makes any confident, generalizable conclusion about socialization outcomes considerably harder to reach than either side of the public debate typically acknowledges.", "Enrollment figures suggest homeschooling grew modestly but steadily through the two decades preceding 2020, before rising sharply during the initial phase of the COVID-19 pandemic, when school closures prompted many families to try homeschooling out of immediate necessity rather than considered preference. Whether this pandemic-era surge represents a durable shift in how families approach education, or merely a temporary spike that will substantially recede once families judge conventional schooling to have fully normalized again, is a question enrollment data collected several years after the pandemic's peak has only begun, tentatively, to address.", "Regulatory approaches to homeschooling vary considerably even within single countries, let alone across them: some jurisdictions require only a simple notification of intent to homeschool, others mandate periodic standardized testing or portfolio review, and a smaller number require homeschooling parents to hold specific educational qualifications before they may legally teach their own children. Advocates for lighter regulation argue that testing requirements disproportionately burden families without meaningfully identifying the small minority of cases where a child's education is genuinely inadequate, whereas proponents of stronger oversight counter that the absence of any assessment mechanism risks leaving inadequately educated children entirely undetected until, in the most severe documented cases, serious harm has already occurred.", "Considered together, the research literature on homeschooling supports far fewer confident generalizations than either side of the public debate typically claims, constrained as it is by self-selected samples, inconsistent measurement approaches, and a regulatory landscape too varied to support any single, universally applicable conclusion about outcomes. Whether future research employing more rigorous sampling methods will resolve these persistent uncertainties, or whether the practice's sheer diversity of motivation and implementation will continue to resist any single explanatory framework, remains a question current researchers answer with considerably more caution than the confidence found in most popular commentary on the subject."], questions: [{ q: "What is the main idea of the passage?", options: ["Homeschooling research has fully resolved the socialization debate conclusively.", "Research proves definitively that homeschooled children always outperform peers.", "Regulatory variation is the only factor affecting homeschooling research quality.", "Selection bias and inconsistent measures limit confident conclusions about homeschooling outcomes."], answer: 3 }, { q: "According to the passage, why might claims of homeschooled children's superior academic outcomes be overstated?", options: ["Because homeschooling motivations have remained identical since the 1970s.", "Because study samples rely on self-selected, more academically engaged families.", "Because standardized tests are banned for homeschooled children entirely.", "Because homeschooled children are proven to perform worse than peers."], answer: 1 }, { q: "According to the passage, what remains uncertain about the pandemic-era rise in homeschooling enrollment?", options: ["Whether enrollment figures were recorded accurately before 2020.", "Whether the rise represents a durable shift or a temporary spike.", "Whether school closures were caused by rising homeschooling rates.", "Whether homeschooling existed at all before the pandemic began."], answer: 1 }, { q: "According to the passage, what do advocates for lighter homeschooling regulation argue?", options: ["Testing requirements burden families without meaningfully identifying inadequate education cases.", "Educational qualifications should be mandatory for all homeschooling parents.", "Standardized testing always identifies every case of inadequate education successfully.", "No jurisdiction currently requires any notification of homeschooling intent."], answer: 0 }, { q: "According to the passage, which of the following is NOT presented as a documented motivation for choosing homeschooling?", options: ["A desire for greater flexibility in scheduling and pacing.", "A guarantee of higher standardized test scores than conventional schools.", "Dissatisfaction with school safety or a child's particular learning needs.", "Religious conviction and dissatisfaction with secular curricula."], answer: 1 }, { q: "The word \"disentangling\" in paragraph 2 is closest in meaning to _______.", options: ["financially supporting", "completely ignoring", "entangling", "separating out"], answer: 3 }, { q: "The word \"durable\" in paragraph 5 is closest in meaning to _______.", options: ["temporary", "financially costly", "durability", "lasting"], answer: 3 }, { q: "The word \"this\" in paragraph 3 (\"this selection bias\") refers to _______.", options: ["self-selected volunteer families", "achievement gap size", "standardized test results", "academic engagement levels"], answer: 0 }, { q: "What can be inferred from the passage about confident claims regarding homeschooling's effects on children?", options: ["Such claims often exceed what the current, methodologically limited research supports.", "Homeschooled children definitely receive better socialization than schooled peers.", "Selection bias caused researchers to invent the socialization debate entirely.", "Such claims are entirely fabricated and have no basis in any research."], answer: 0 }, { q: "How does the author primarily structure the argument in this passage?", options: ["By arguing that all homeschooling regulation should be abolished immediately.", "By concluding decisively that pandemic-era homeschooling growth will fully reverse.", "By proving conclusively that homeschooling produces superior educational outcomes.", "By presenting homeschooling's research base while consistently highlighting its methodological limitations."], answer: 3 }] },
  ] },
];
